import{_ as t,o as n,c as e,ag as r}from"./chunks/framework.Dx86EdC1.js";const p=JSON.parse('{"title":"Portal Layanan Mandiri Warga","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/portal-warga.md","filePath":"panduan-pengguna/portal-warga.md","lastUpdated":1791382762000}'),i={name:"panduan-pengguna/portal-warga.md"};function o(s,a,u,d,l,g){return n(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="portal-layanan-mandiri-warga" tabindex="-1">Portal Layanan Mandiri Warga <a class="header-anchor" href="#portal-layanan-mandiri-warga" aria-label="Permalink to &quot;Portal Layanan Mandiri Warga&quot;">​</a></h1><p>Portal warga memungkinkan warga <strong>mengajukan surat tanpa datang ke kantor desa</strong>.</p><h2 id="untuk-warga" tabindex="-1">Untuk Warga <a class="header-anchor" href="#untuk-warga" aria-label="Permalink to &quot;Untuk Warga&quot;">​</a></h2><h3 id="_1-registrasi-login" tabindex="-1">1. Registrasi &amp; Login <a class="header-anchor" href="#_1-registrasi-login" aria-label="Permalink to &quot;1. Registrasi &amp; Login&quot;">​</a></h3><ul><li>Daftar di <code>/login</code> → <strong>Daftar Akun</strong> (<code>/register</code>).</li><li>Isi data diri + centang <strong>persetujuan pemrosesan data pribadi</strong> (wajib, UU PDP No. 27/2022).</li><li>Akun diverifikasi desa (opsional: dibuatkan langsung oleh operator lewat menu Penduduk → <em>Buat Akun</em>).</li></ul><h3 id="_2-ajukan-surat" tabindex="-1">2. Ajukan Surat <a class="header-anchor" href="#_2-ajukan-surat" aria-label="Permalink to &quot;2. Ajukan Surat&quot;">​</a></h3><ol><li>Login → menu <strong>Layanan Surat</strong> (<code>/citizen/letters</code>).</li><li>Klik <strong>Ajukan Surat Baru</strong> (<code>/citizen/letters/create</code>).</li><li>Pilih <strong>template surat yang aktif</strong> (SKTM, SKCK, Domisili, SKU, SKPWNI, dll.).</li><li>Isi field tambahan yang diminta (mis. SKU: data usaha).</li><li><strong>Kirim</strong> — permohonan masuk status <code>pending_rt</code>.</li></ol><h3 id="_3-pantau-status" tabindex="-1">3. Pantau Status <a class="header-anchor" href="#_3-pantau-status" aria-label="Permalink to &quot;3. Pantau Status&quot;">​</a></h3><p>Di daftar permohonan, status tampil real-time:</p><table tabindex="0"><thead><tr><th>Status</th><th>Arti</th></tr></thead><tbody><tr><td>Menunggu Verifikasi RT/RW</td><td>Menunggu Ketua RT</td></tr><tr><td>Menunggu Verifikasi Staf Desa</td><td>RT sudah verifikasi, menunggu operator</td></tr><tr><td>Menunggu TTE Kades</td><td>Menunggu persetujuan Kepala Desa</td></tr><tr><td>Selesai &amp; Disahkan</td><td>Surat siap diunduh</td></tr><tr><td>Ditolak</td><td>Lihat alasan penolakan</td></tr></tbody></table><h3 id="_4-unduh-pdf" tabindex="-1">4. Unduh PDF <a class="header-anchor" href="#_4-unduh-pdf" aria-label="Permalink to &quot;4. Unduh PDF&quot;">​</a></h3><p>Setelah <strong>Selesai &amp; Disahkan</strong>, klik <strong>Unduh PDF</strong> (<code>/citizen/letters/{id}/pdf</code>). Dokumen berisi QR verifikasi — bisa ditunjukkan ke pihak yang menerima surat.</p><h2 id="untuk-operator-desa" tabindex="-1">Untuk Operator Desa <a class="header-anchor" href="#untuk-operator-desa" aria-label="Permalink to &quot;Untuk Operator Desa&quot;">​</a></h2><ul><li><strong>Membuatkan permohonan atas nama warga</strong>: gunakan menu admin <a href="/panduan-pengguna/permohonan-surat.html">Permohonan Surat</a> — data pemohon diambil dari Buku Induk.</li><li><strong>Memberi akses</strong>: buatkan akun lewat Penduduk → <em>Buat Akun</em>, atau ACC registrasi mandiri.</li><li><strong>Memantau antrean</strong>: badge dashboard menunjukkan jumlah permohonan per status.</li></ul><h2 id="privasi-keamanan" tabindex="-1">Privasi &amp; Keamanan <a class="header-anchor" href="#privasi-keamanan" aria-label="Permalink to &quot;Privasi &amp; Keamanan&quot;">​</a></h2><ul><li>Warga hanya melihat <strong>permohonannya sendiri</strong> (query berdasarkan <code>resident_id</code>/user terkait).</li><li>Data pribadi pemohon tidak pernah diekspos ke warga lain.</li><li>Aktivitas pengunduhan tercatat di audit trail desa.</li></ul>',16)])])}const m=t(i,[["render",o]]);export{p as __pageData,m as default};
